 bool newGesture = (maskedAction == AMOTION_EVENT_ACTION_DOWN
 || maskedAction == AMOTION_EVENT_ACTION_SCROLL
 || isHoverAction);
 bool wrongDevice = false;
 if (newGesture) {
 bool down = maskedAction == AMOTION_EVENT_ACTION_DOWN;
 if (switchedDevice && mTempTouchState.down && !down) {
#if DEBUG_FOCUS
            ALOGD("Dropping event because a pointer for a different device is already down.");
#endif
            injectionResult = INPUT_EVENT_INJECTION_FAILED;
            switchedDevice = false;
            wrongDevice = true;
 goto Failed;
 }
        mTempTouchState.reset();
        mTempTouchState.down = down;
        mTempTouchState.deviceId = entry->deviceId;
        mTempTouchState.source = entry->source;
        mTempTouchState.displayId = displayId;
        isSplit = false;
 }

 if (newGesture || (isSplit && maskedAction == AMOTION_EVENT_ACTION_POINTER_DOWN)) {
 /* Case 1: New splittable pointer going down, or need target for hover or scroll. */

 int32_t pointerIndex = getMotionEventActionPointerIndex(action);
 int32_t x = int32_t(entry->pointerCoords[pointerIndex].
                getAxisValue(AMOTION_EVENT_AXIS_X));
 int32_t y = int32_t(entry->pointerCoords[pointerIndex].
                getAxisValue(AMOTION_EVENT_AXIS_Y));
        sp<InputWindowHandle> newTouchedWindowHandle;
 bool isTouchModal = false;

 size_t numWindows = mWindowHandles.size();
 for (size_t i = 0; i < numWindows; i++) {
            sp<InputWindowHandle> windowHandle = mWindowHandles.itemAt(i);
 const InputWindowInfo* windowInfo = windowHandle->getInfo();
 if (windowInfo->displayId != displayId) {
 continue; // wrong display
 }

 int32_t flags = windowInfo->layoutParamsFlags;
 if (windowInfo->visible) {
 if (! (flags & InputWindowInfo::FLAG_NOT_TOUCHABLE)) {
                    isTouchModal = (flags & (InputWindowInfo::FLAG_NOT_FOCUSABLE
 | InputWindowInfo::FLAG_NOT_TOUCH_MODAL)) == 0;
 if (isTouchModal || windowInfo->touchableRegionContainsPoint(x, y)) {
                        newTouchedWindowHandle = windowHandle;
 break; // found touched window, exit window loop
 }
 }

 if (maskedAction == AMOTION_EVENT_ACTION_DOWN
 && (flags & InputWindowInfo::FLAG_WATCH_OUTSIDE_TOUCH)) {

                     int32_t outsideTargetFlags = InputTarget::FLAG_DISPATCH_AS_OUTSIDE;
                     if (isWindowObscuredAtPointLocked(windowHandle, x, y)) {
                         outsideTargetFlags |= InputTarget::FLAG_WINDOW_IS_OBSCURED;
                     }

                     mTempTouchState.addOrUpdateWindow(
                            windowHandle, outsideTargetFlags, BitSet32(0));
 }
 }
 }

 if (newTouchedWindowHandle != NULL
 && newTouchedWindowHandle->getInfo()->supportsSplitTouch()) {
            isSplit = true;
 } else if (isSplit) {
            newTouchedWindowHandle = NULL;
 }

 if (newTouchedWindowHandle == NULL) {
            newTouchedWindowHandle = mTempTouchState.getFirstForegroundWindowHandle();
 if (newTouchedWindowHandle == NULL) {
                ALOGI("Dropping event because there is no touchable window at (%d, %d).", x, y);
                injectionResult = INPUT_EVENT_INJECTION_FAILED;
 goto Failed;
 }
 }

 int32_t targetFlags = InputTarget::FLAG_FOREGROUND | InputTarget::FLAG_DISPATCH_AS_IS;
 if (isSplit) {
            targetFlags |= InputTarget::FLAG_SPLIT;

         }
         if (isWindowObscuredAtPointLocked(newTouchedWindowHandle, x, y)) {
             targetFlags |= InputTarget::FLAG_WINDOW_IS_OBSCURED;
         }

 if (isHoverAction) {
            newHoverWindowHandle = newTouchedWindowHandle;
 } else if (maskedAction == AMOTION_EVENT_ACTION_SCROLL) {
            newHoverWindowHandle = mLastHoverWindowHandle;
 }

 BitSet32 pointerIds;
 if (isSplit) {
 uint32_t pointerId = entry->pointerProperties[pointerIndex].id;
            pointerIds.markBit(pointerId);
 }
        mTempTouchState.addOrUpdateWindow(newTouchedWindowHandle, targetFlags, pointerIds);
 } else {
 /* Case 2: Pointer move, up, cancel or non-splittable pointer down. */

 if (! mTempTouchState.down) {
#if DEBUG_FOCUS
            ALOGD("Dropping event because the pointer is not down or we previously "
 "dropped the pointer down event.");
#endif
            injectionResult = INPUT_EVENT_INJECTION_FAILED;
 goto Failed;
 }

 if (maskedAction == AMOTION_EVENT_ACTION_MOVE
 && entry->pointerCount == 1
 && mTempTouchState.isSlippery()) {
 int32_t x = int32_t(entry->pointerCoords[0].getAxisValue(AMOTION_EVENT_AXIS_X));
 int32_t y = int32_t(entry->pointerCoords[0].getAxisValue(AMOTION_EVENT_AXIS_Y));

            sp<InputWindowHandle> oldTouchedWindowHandle =
                    mTempTouchState.getFirstForegroundWindowHandle();
            sp<InputWindowHandle> newTouchedWindowHandle =
                    findTouchedWindowAtLocked(displayId, x, y);
 if (oldTouchedWindowHandle != newTouchedWindowHandle
 && newTouchedWindowHandle != NULL) {
#if DEBUG_FOCUS
                ALOGD("Touch is slipping out of window %s into window %s.",
                        oldTouchedWindowHandle->getName().string(),
                        newTouchedWindowHandle->getName().string());
#endif
                mTempTouchState.addOrUpdateWindow(oldTouchedWindowHandle,
 InputTarget::FLAG_DISPATCH_AS_SLIPPERY_EXIT, BitSet32(0));

 if (newTouchedWindowHandle->getInfo()->supportsSplitTouch()) {
                    isSplit = true;
 }

 int32_t targetFlags = InputTarget::FLAG_FOREGROUND
 | InputTarget::FLAG_DISPATCH_AS_SLIPPERY_ENTER;
 if (isSplit) {
                    targetFlags |= InputTarget::FLAG_SPLIT;
 }
 if (isWindowObscuredAtPointLocked(newTouchedWindowHandle, x, y)) {
                    targetFlags |= InputTarget::FLAG_WINDOW_IS_OBSCURED;
 }

 BitSet32 pointerIds;
 if (isSplit) {
                    pointerIds.markBit(entry->pointerProperties[0].id);
 }
                mTempTouchState.addOrUpdateWindow(newTouchedWindowHandle, targetFlags, pointerIds);
 }
 }
 }

 if (newHoverWindowHandle != mLastHoverWindowHandle) {
 if (mLastHoverWindowHandle != NULL) {
#if DEBUG_HOVER
            ALOGD("Sending hover exit event to window %s.",
                    mLastHoverWindowHandle->getName().string());
#endif
            mTempTouchState.addOrUpdateWindow(mLastHoverWindowHandle,
 InputTarget::FLAG_DISPATCH_AS_HOVER_EXIT, BitSet32(0));
 }

 if (newHoverWindowHandle != NULL) {
#if DEBUG_HOVER
            ALOGD("Sending hover enter event to window %s.",
                    newHoverWindowHandle->getName().string());
#endif
            mTempTouchState.addOrUpdateWindow(newHoverWindowHandle,
 InputTarget::FLAG_DISPATCH_AS_HOVER_ENTER, BitSet32(0));
 }
 }

 {
 bool haveForegroundWindow = false;
 for (size_t i = 0; i < mTempTouchState.windows.size(); i++) {
 const TouchedWindow& touchedWindow = mTempTouchState.windows[i];
 if (touchedWindow.targetFlags & InputTarget::FLAG_FOREGROUND) {
                haveForegroundWindow = true;
 if (! checkInjectionPermission(touchedWindow.windowHandle,
                        entry->injectionState)) {
                    injectionResult = INPUT_EVENT_INJECTION_PERMISSION_DENIED;
                    injectionPermission = INJECTION_PERMISSION_DENIED;
 goto Failed;
 }
 }
 }
 if (! haveForegroundWindow) {
#if DEBUG_FOCUS
            ALOGD("Dropping event because there is no touched foreground window to receive it.");
#endif
            injectionResult = INPUT_EVENT_INJECTION_FAILED;
 goto Failed;
 }

        injectionPermission = INJECTION_PERMISSION_GRANTED;
 }

 if (maskedAction == AMOTION_EVENT_ACTION_DOWN) {
        sp<InputWindowHandle> foregroundWindowHandle =
                mTempTouchState.getFirstForegroundWindowHandle();
 const int32_t foregroundWindowUid = foregroundWindowHandle->getInfo()->ownerUid;
 for (size_t i = 0; i < mTempTouchState.windows.size(); i++) {
 const TouchedWindow& touchedWindow = mTempTouchState.windows[i];
 if (touchedWindow.targetFlags & InputTarget::FLAG_DISPATCH_AS_OUTSIDE) {
                sp<InputWindowHandle> inputWindowHandle = touchedWindow.windowHandle;
 if (inputWindowHandle->getInfo()->ownerUid != foregroundWindowUid) {
                    mTempTouchState.addOrUpdateWindow(inputWindowHandle,
 InputTarget::FLAG_ZERO_COORDS, BitSet32(0));
 }
 }
 }
 }

 for (size_t i = 0; i < mTempTouchState.windows.size(); i++) {
 const TouchedWindow& touchedWindow = mTempTouchState.windows[i];
 if (touchedWindow.targetFlags & InputTarget::FLAG_FOREGROUND) {
 String8 reason = checkWindowReadyForMoreInputLocked(currentTime,
                    touchedWindow.windowHandle, entry, "touched");
 if (!reason.isEmpty()) {
                injectionResult = handleTargetsNotReadyLocked(currentTime, entry,
                        NULL, touchedWindow.windowHandle, nextWakeupTime, reason.string());
 goto Unresponsive;
 }
 }
 }

 if (maskedAction == AMOTION_EVENT_ACTION_DOWN) {
        sp<InputWindowHandle> foregroundWindowHandle =
                mTempTouchState.getFirstForegroundWindowHandle();
 if (foregroundWindowHandle->getInfo()->hasWallpaper) {
 for (size_t i = 0; i < mWindowHandles.size(); i++) {
                sp<InputWindowHandle> windowHandle = mWindowHandles.itemAt(i);
 const InputWindowInfo* info = windowHandle->getInfo();
 if (info->displayId == displayId
 && windowHandle->getInfo()->layoutParamsType

                                 == InputWindowInfo::TYPE_WALLPAPER) {
                     mTempTouchState.addOrUpdateWindow(windowHandle,
                             InputTarget::FLAG_WINDOW_IS_OBSCURED
                                     | InputTarget::FLAG_DISPATCH_AS_IS,
                             BitSet32(0));
                 }
 }
 }
 }

    injectionResult = INPUT_EVENT_INJECTION_SUCCEEDED;

 for (size_t i = 0; i < mTempTouchState.windows.size(); i++) {
 const TouchedWindow& touchedWindow = mTempTouchState.windows.itemAt(i);
        addWindowTargetLocked(touchedWindow.windowHandle, touchedWindow.targetFlags,
                touchedWindow.pointerIds, inputTargets);
 }

    mTempTouchState.filterNonAsIsTouchWindows();

Failed:
 if (injectionPermission == INJECTION_PERMISSION_UNKNOWN) {
 if (checkInjectionPermission(NULL, entry->injectionState)) {
            injectionPermission = INJECTION_PERMISSION_GRANTED;
 } else {
            injectionPermission = INJECTION_PERMISSION_DENIED;
 }
 }

 if (injectionPermission == INJECTION_PERMISSION_GRANTED) {
 if (!wrongDevice) {
 if (switchedDevice) {
#if DEBUG_FOCUS
                ALOGD("Conflicting pointer actions: Switched to a different device.");
#endif
 *outConflictingPointerActions = true;
 }

 if (isHoverAction) {
 if (oldState && oldState->down) {
#if DEBUG_FOCUS
                    ALOGD("Conflicting pointer actions: Hover received while pointer was down.");
#endif
 *outConflictingPointerActions = true;
 }
                mTempTouchState.reset();
 if (maskedAction == AMOTION_EVENT_ACTION_HOVER_ENTER
 || maskedAction == AMOTION_EVENT_ACTION_HOVER_MOVE) {
                    mTempTouchState.deviceId = entry->deviceId;
                    mTempTouchState.source = entry->source;
                    mTempTouchState.displayId = displayId;
 }
 } else if (maskedAction == AMOTION_EVENT_ACTION_UP
 || maskedAction == AMOTION_EVENT_ACTION_CANCEL) {
                mTempTouchState.reset();
 } else if (maskedAction == AMOTION_EVENT_ACTION_DOWN) {
 if (oldState && oldState->down) {
#if DEBUG_FOCUS
                    ALOGD("Conflicting pointer actions: Down received while already down.");
#endif
 *outConflictingPointerActions = true;
 }
 } else if (maskedAction == AMOTION_EVENT_ACTION_POINTER_UP) {
 if (isSplit) {
 int32_t pointerIndex = getMotionEventActionPointerIndex(action);
 uint32_t pointerId = entry->pointerProperties[pointerIndex].id;

 for (size_t i = 0; i < mTempTouchState.windows.size(); ) {
 TouchedWindow& touchedWindow = mTempTouchState.windows.editItemAt(i);
 if (touchedWindow.targetFlags & InputTarget::FLAG_SPLIT) {
                            touchedWindow.pointerIds.clearBit(pointerId);
 if (touchedWindow.pointerIds.isEmpty()) {
                                mTempTouchState.windows.removeAt(i);
 continue;
 }
 }
                        i += 1;
 }
 }
 }

 if (maskedAction != AMOTION_EVENT_ACTION_SCROLL) {
 if (mTempTouchState.displayId >= 0) {
 if (oldStateIndex >= 0) {
                        mTouchStatesByDisplay.editValueAt(oldStateIndex).copyFrom(mTempTouchState);
 } else {
                        mTouchStatesByDisplay.add(displayId, mTempTouchState);
 }
 } else if (oldStateIndex >= 0) {
                    mTouchStatesByDisplay.removeItemsAt(oldStateIndex);
 }
 }

            mLastHoverWindowHandle = newHoverWindowHandle;
 }
 } else {
#if DEBUG_FOCUS
        ALOGD("Not updating touch focus because injection was denied.");
#endif
 }

Unresponsive:
    mTempTouchState.reset();

 nsecs_t timeSpentWaitingForApplication = getTimeSpentWaitingForApplicationLocked(currentTime);
    updateDispatchStatisticsLocked(currentTime, entry,
            injectionResult, timeSpentWaitingForApplication);
#if DEBUG_FOCUS
    ALOGD("findTouchedWindow finished: injectionResult=%d, injectionPermission=%d, "
 "timeSpentWaitingForApplication=%0.1fms",
            injectionResult, injectionPermission, timeSpentWaitingForApplication / 1000000.0);
#endif
 return injectionResult;
}
,CWE-264,CVE-2016-2496,"Add new MotionEvent flag for partially obscured windows.

 cib_remote_listen(gpointer data)
 {
    int lpc = 0;
     int csock = 0;
     unsigned laddr;
    time_t now = 0;
    time_t start = time(NULL);
     struct sockaddr_in addr;
     int ssock = *(int *)data;

 #ifdef HAVE_GNUTLS_GNUTLS_H
     gnutls_session *session = NULL;
 #endif
     cib_client_t *new_client = NULL;

    xmlNode *login = NULL;
    const char *user = NULL;
    const char *pass = NULL;
    const char *tmp = NULL;
#ifdef HAVE_DECL_NANOSLEEP
    const struct timespec sleepfast = { 0, 10000000 };  /* 10 millisec */
#endif
     static struct mainloop_fd_callbacks remote_client_fd_callbacks = 
         {
             .dispatch = cib_remote_msg,
             .destroy = cib_remote_connection_destroy,
        };    
     /* accept the connection */
     laddr = sizeof(addr);
     csock = accept(ssock, (struct sockaddr *)&addr, &laddr);
    crm_debug("New %s connection from %s",
              ssock == remote_tls_fd ? "secure" : "clear-text", inet_ntoa(addr.sin_addr));

    if (csock == -1) {
        crm_err("accept socket failed");
         return TRUE;
     }

     if (ssock == remote_tls_fd) {
 #ifdef HAVE_GNUTLS_GNUTLS_H
         /* create gnutls session for the server socket */
        session = create_tls_session(csock, GNUTLS_SERVER);
         if (session == NULL) {
             crm_err("TLS session creation failed");
             close(csock);
            return TRUE;
        }
 #endif
     }

    do {
        crm_trace("Iter: %d", lpc++);
        if (ssock == remote_tls_fd) {
#ifdef HAVE_GNUTLS_GNUTLS_H
            login = crm_recv_remote_msg(session, TRUE);
#endif
        } else {
            login = crm_recv_remote_msg(GINT_TO_POINTER(csock), FALSE);
        }
        if (login != NULL) {
            break;
        }
#ifdef HAVE_DECL_NANOSLEEP
        nanosleep(&sleepfast, NULL);
#else
        sleep(1);
#endif
        now = time(NULL);
        /* Peers have 3s to connect */
    } while (login == NULL && (start - now) < 4);
    crm_log_xml_info(login, "Login: ");
    if (login == NULL) {
        goto bail;
    }
    tmp = crm_element_name(login);
    if (safe_str_neq(tmp, "cib_command")) {
        crm_err("Wrong tag: %s", tmp);
        goto bail;
    }
    tmp = crm_element_value(login, "op");
    if (safe_str_neq(tmp, "authenticate")) {
        crm_err("Wrong operation: %s", tmp);
        goto bail;
    }
    user = crm_element_value(login, "user");
    pass = crm_element_value(login, "password");
    /* Non-root daemons can only validate the password of the
     * user they're running as
     */
    if (check_group_membership(user, CRM_DAEMON_GROUP) == FALSE) {
        crm_err("User is not a member of the required group");
        goto bail;
    } else if (authenticate_user(user, pass) == FALSE) {
        crm_err("PAM auth failed");
        goto bail;
    }
    /* send ACK */
     num_clients++;
     new_client = calloc(1, sizeof(cib_client_t));
    new_client->name = crm_element_value_copy(login, "name");
    CRM_CHECK(new_client->id == NULL, free(new_client->id));
     new_client->id = crm_generate_uuid();
#if ENABLE_ACL
    new_client->user = strdup(user);
#endif
     new_client->callback_id = NULL;
     if (ssock == remote_tls_fd) {
 #ifdef HAVE_GNUTLS_GNUTLS_H
         new_client->encrypted = TRUE;
        new_client->session = session;
#endif
    } else {
         new_client->session = GINT_TO_POINTER(csock);
     }

    free_xml(login);
    login = create_xml_node(NULL, "cib_result");
    crm_xml_add(login, F_CIB_OPERATION, CRM_OP_REGISTER);
    crm_xml_add(login, F_CIB_CLIENTID, new_client->id);
    crm_send_remote_msg(new_client->session, login, new_client->encrypted);
    free_xml(login);
     new_client->remote = mainloop_add_fd(
         "cib-remote-client", G_PRIORITY_DEFAULT, csock, new_client, &remote_client_fd_callbacks);

     g_hash_table_insert(client_list, new_client->id, new_client);

     return TRUE;
  bail:
    if (ssock == remote_tls_fd) {
#ifdef HAVE_GNUTLS_GNUTLS_H
        gnutls_bye(*session, GNUTLS_SHUT_RDWR);
        gnutls_deinit(*session);
        gnutls_free(session);
#endif
    }
    close(csock);
    free_xml(login);
    return TRUE;
 }
,CWE-399,CVE-2013-0281,High: core: Internal tls api improvements for reuse with future LRMD tls backend.,pacemaker,1,Type: CWE-399 | Context: High: core: Internal tls api improvements for reuse with future LRMD tls backend.

 static inline int mount_entry_on_generic(struct mntent *mntent,
                 const char* path)
 {
 	unsigned long mntflags;
 	char *mntdata;
	int ret;
	bool optional = hasmntopt(mntent, "optional") != NULL;

	ret = mount_entry_create_dir_file(mntent, path);

	if (ret < 0)
		return optional ? 0 : -1;

	cull_mntent_opt(mntent);

	if (parse_mntopts(mntent->mnt_opts, &mntflags, &mntdata) < 0) {
		free(mntdata);
		return -1;
 	}

 	ret = mount_entry(mntent->mnt_fsname, path, mntent->mnt_type,
			  mntflags, mntdata, optional);

 	free(mntdata);

	return ret;
}
